     1→"use server";
     2→
     3→import { action, authAction } from "@/lib/actions/safe-actions";
     4→import { prisma } from "@/lib/prisma";
     5→import { z } from "zod";
     6→import { nanoid } from "nanoid";
     7→import { sendEmail } from "@/lib/mail/send-email";
     8→import MarkdownEmail from "@email/markdown.email";
     9→import { getServerUrl } from "@/lib/server-url";
    10→
    11→// ═══════════════════════════════════════════════════════════════
    12→// CAREGIVER RELATIONSHIP SYSTEM
    13→// ═══════════════════════════════════════════════════════════════
    14→
    15→// ===== Invite a Caregiver =====
    16→
    17→const inviteCaregiverSchema = z.object({
    18→  email: z.string().email(),
    19→  role: z.enum(["family", "friend", "professional"]),
    20→  label: z.string().optional(),
    21→  permissions: z
    22→    .array(z.string())
    23→    .default(["view_mood", "add_observations", "add_events"]),
    24→});
    25→
    26→const roleLabels: Record<string, string> = {
    27→  family: "membre de la famille",
    28→  friend: "ami",
    29→  professional: "professionnel de santé",
    30→};
    31→
    32→const sendCaregiverInviteEmail = async (params: {
    33→  email: string;
    34→  inviteToken: string;
    35→  patientName: string | null | undefined;
    36→  role: string;
    37→  label?: string | null;
    38→}) => {
    39→  const inviteUrl = `${getServerUrl()}/invite/caregiver?token=${params.inviteToken}`;
    40→  const patientName = params.patientName?.trim().length
    41→    ? params.patientName
    42→    : "Un proche";
    43→  const roleLabel = roleLabels[params.role] ?? "aidant";
    44→  const labelLine = params.label?.trim()
    45→    ? `Il/elle vous identifie comme **${params.label}**.`
    46→    : "";
    47→
    48→  const markdown = `
    49→Bonjour,
    50→
    51→${patientName} vous invite à rejoindre son cercle Moodday en tant que ${roleLabel}.
    52→${labelLine}
    53→
    54→Cliquez ici pour accepter l'invitation :
    55→${inviteUrl}
    56→
    57→Si vous ne connaissez pas cette personne, vous pouvez ignorer cet email.
    58→`;
    59→
    60→  await sendEmail({
    61→    to: params.email,
    62→    subject: "Invitation à rejoindre Moodday",
    63→    html: MarkdownEmail({
    64→      markdown,
    65→      preview: `${patientName} vous invite sur Moodday`,
    66→    }),
    67→  });
    68→};
    69→
    70→export const inviteCaregiver = authAction
    71→  .inputSchema(inviteCaregiverSchema)
    72→  .action(
    73→    async ({
    74→      parsedInput: { email, role, label, permissions },
    75→      ctx: { user },
    76→    }) => {
    77→      // Check if user is trying to invite themselves
    78→      if (email === user.email) {
    79→        throw new Error("Vous ne pouvez pas vous inviter vous-même");
    80→      }
    81→
    82→      // Check if caregiver user exists
    83→      const caregiverUser = await prisma.user.findUnique({
    84→        where: { email },
    85→        select: { id: true, name: true, email: true },
    86→      });
    87→
    88→      const existingRelation = await prisma.caregiverRelationship.findFirst({
    89→        where: {
    90→          patientId: user.id,
    91→          OR: [
    92→            { caregiverEmail: email },
    93→            ...(caregiverUser ? [{ caregiverId: caregiverUser.id }] : []),
    94→          ],
    95→        },
    96→      });
    97→
    98→      // Generate invite token
    99→      const inviteToken = nanoid(32);
   100→      const inviteExpiry = new Date();
   101→      inviteExpiry.setDate(inviteExpiry.getDate() + 7); // 7 days validity
   102→
   103→      if (existingRelation) {
   104→        if (existingRelation.status === "active") {
   105→          throw new Error("Cette personne fait déjà partie de votre cercle");
   106→        }
   107→
   108→        if (
   109→          existingRelation.status === "pending" &&
   110→          existingRelation.inviteExpiry &&
   111→          existingRelation.inviteExpiry > new Date()
   112→        ) {
   113→          throw new Error(
   114→            "Une invitation est déjà en attente pour cette personne",
   115→          );
   116→        }
   117→
   118→        const updated = await prisma.caregiverRelationship.update({
   119→          where: { id: existingRelation.id },
   120→          data: {
   121→            caregiverId: caregiverUser?.id ?? null,
   122→            caregiverEmail: email,
   123→            role,
   124→            label,
   125→            permissions,
   126→            status: "pending",
   127→            inviteToken,
   128→            inviteExpiry,
   129→          },
   130→        });
   131→
   132→        await sendCaregiverInviteEmail({
   133→          email,
   134→          inviteToken,
   135→          patientName: user.name,
   136→          role,
   137→          label,
   138→        });
   139→
   140→        return {
   141→          id: updated.id,
   142→          inviteToken,
   143→          caregiverExists: !!caregiverUser,
   144→        };
   145→      }
   146→
   147→      // Create the relationship
   148→      const relationship = await prisma.caregiverRelationship.create({
   149→        data: {
   150→          patientId: user.id,
   151→          caregiverId: caregiverUser?.id ?? null,
   152→          caregiverEmail: email,
   153→          role,
   154→          label,
   155→          permissions,
   156→          status: "pending",
   157→          inviteToken,
   158→          inviteExpiry,
   159→        },
   160→      });
   161→
   162→      await sendCaregiverInviteEmail({
   163→        email,
   164→        inviteToken,
   165→        patientName: user.name,
   166→        role,
   167→        label,
   168→      });
   169→
   170→      return {
   171→        id: relationship.id,
   172→        inviteToken,
   173→        caregiverExists: !!caregiverUser,
   174→      };
   175→    },
   176→  );
   177→
   178→// ===== Get Invitation Info (public) =====
   179→
   180→const inviteInfoSchema = z.object({
   181→  inviteToken: z.string(),
   182→});
   183→
   184→export const getCaregiverInviteInfo = action
   185→  .inputSchema(inviteInfoSchema)
   186→  .action(async ({ parsedInput: { inviteToken } }) => {
   187→    const relationship = await prisma.caregiverRelationship.findUnique({
   188→      where: { inviteToken },
   189→      include: {
   190→        patient: { select: { name: true, email: true, image: true } },
   191→      },
   192→    });
   193→
   194→    if (!relationship) {
   195→      throw new Error("Invitation invalide ou expirée");
   196→    }
   197→
   198→    if (relationship.inviteExpiry && relationship.inviteExpiry < new Date()) {
   199→      throw new Error("Cette invitation a expiré");
   200→    }
   201→
   202→    return {
   203→      id: relationship.id,
   204→      status: relationship.status,
   205→      role: relationship.role,
   206→      label: relationship.label,
   207→      patientName: relationship.patient.name,
   208→      patientEmail: relationship.patient.email,
   209→      patientImage: relationship.patient.image,
   210→      inviteExpiry: relationship.inviteExpiry?.toISOString() ?? null,
   211→    };
   212→  });
   213→
   214→// ===== Accept Caregiver Invitation =====
   215→
   216→const acceptInvitationSchema = z.object({
   217→  inviteToken: z.string(),
   218→});
   219→
   220→export const acceptCaregiverInvitation = authAction
   221→  .inputSchema(acceptInvitationSchema)
   222→  .action(async ({ parsedInput: { inviteToken }, ctx: { user } }) => {
   223→    const relationship = await prisma.caregiverRelationship.findUnique({
   224→      where: { inviteToken },
   225→      include: {
   226→        patient: { select: { name: true } },
   227→      },
   228→    });
   229→
   230→    if (!relationship) {
   231→      throw new Error("Invitation invalide ou expirée");
   232→    }
   233→
   234→    if (relationship.inviteExpiry && relationship.inviteExpiry < new Date()) {
   235→      throw new Error("Cette invitation a expiré");
   236→    }
   237→
   238→    if (relationship.status === "active") {
   239→      throw new Error("Cette invitation a déjà été acceptée");
   240→    }
   241→
   242→    if (relationship.patientId === user.id) {
   243→      throw new Error("Vous ne pouvez pas accepter votre propre invitation");
   244→    }
   245→
   246→    if (
   247→      relationship.caregiverEmail &&
   248→      relationship.caregiverEmail !== user.email
   249→    ) {
   250→      throw new Error("Cette invitation ne vous est pas destinée");
   251→    }
   252→
   253→    if (relationship.caregiverId && relationship.caregiverId !== user.id) {
   254→      throw new Error("Cette invitation ne vous est pas destinée");
   255→    }
   256→
   257→    // Update the relationship
   258→    const updated = await prisma.caregiverRelationship.update({
   259→      where: { id: relationship.id },
   260→      data: {
   261→        caregiverId: user.id,
   262→        caregiverEmail: user.email,
   263→        status: "active",
   264→        inviteToken: null,
   265→        inviteExpiry: null,
   266→      },
   267→    });
   268→
   269→    return {
   270→      id: updated.id,
   271→      patientName: relationship.patient.name,
   272→    };
   273→  });
   274→
   275→// ===== Decline Caregiver Invitation =====
   276→
   277→export const declineCaregiverInvitation = authAction
   278→  .inputSchema(acceptInvitationSchema)
   279→  .action(async ({ parsedInput: { inviteToken }, ctx: { user } }) => {
   280→    const relationship = await prisma.caregiverRelationship.findUnique({
   281→      where: { inviteToken },
   282→    });
   283→
   284→    if (!relationship) {
   285→      throw new Error("Invitation invalide");
   286→    }
   287→
   288→    if (
   289→      relationship.caregiverEmail &&
   290→      relationship.caregiverEmail !== user.email
   291→    ) {
   292→      throw new Error("Cette invitation ne vous est pas destinée");
   293→    }
   294→
   295→    if (relationship.caregiverId && relationship.caregiverId !== user.id) {
   296→      throw new Error("Cette invitation ne vous est pas destinée");
   297→    }
   298→
   299→    await prisma.caregiverRelationship.update({
   300→      where: { id: relationship.id },
   301→      data: {
   302→        status: "declined",
   303→        inviteToken: null,
   304→        inviteExpiry: null,
   305→      },
   306→    });
   307→
   308→    return { success: true };
   309→  });
   310→
   311→// ===== Get My Caregivers (as patient) =====
   312→
   313→export const getMyCaregivers = authAction.action(async ({ ctx: { user } }) => {
   314→  const relationships = await prisma.caregiverRelationship.findMany({
   315→    where: {
   316→      patientId: user.id,
   317→    },
   318→    include: {
   319→      caregiver: {
   320→        select: { id: true, name: true, email: true, image: true },
   321→      },
   322→    },
   323→    orderBy: { createdAt: "desc" },
